css:
:root {
  --bg: #14161a; --card: #1e2127; --line: #2c3038; --fg: #e6e8eb; --dim: #8b919b;
  --math: #e0a84f; --cs: #4fa3e0; --eng: #6cc98a; --pol: #d46a6a; --accent: #e0a84f;
  --ok: #6cc98a;
}
* { box-sizing: border-box; }
html, body { margin: 0; background: var(--bg); color: var(--fg);
  font: 15px/1.5 -apple-system, "PingFang SC", "Microsoft YaHei", "Segoe UI", sans-serif; }
button { font: inherit; color: inherit; background: var(--line); border: 0; border-radius: 8px;
  padding: 8px 14px; cursor: pointer; }
button:active { transform: scale(.97); }
button.primary { background: var(--accent); color: #111; font-weight: 600; }
button.ghost { background: transparent; border: 1px solid var(--line); }
input, select, textarea { font: inherit; color: var(--fg); background: var(--bg); border: 1px solid var(--line);
  border-radius: 8px; padding: 8px 10px; width: 100%; }
textarea { resize: vertical; min-height: 60px; }
label { color: var(--dim); font-size: 13px; display: block; margin: 10px 0 4px; }
.hidden { display: none !important; }
.dim { color: var(--dim); font-size: 13px; }

header { position: sticky; top: 0; z-index: 5; background: var(--bg); border-bottom: 1px solid var(--line);
  padding: calc(10px + env(safe-area-inset-top)) 16px 10px; }
.top { display: flex; justify-content: space-between; align-items: center; max-width: 760px; margin: 0 auto; }
.hdate { font-size: 18px; font-weight: 600; }
.hphase { color: var(--dim); font-size: 12px; }
.right { display: flex; gap: 12px; align-items: center; }
.hcount { white-space: nowrap; text-align: right; font-size: 13px; color: var(--dim); }
.hcount b { color: var(--accent); font-size: 18px; }
.sync { white-space: nowrap; background: transparent; padding: 4px 8px; font-size: 14px; color: var(--dim); }
.sync.ok { color: var(--ok); } .sync.err { color: var(--pol); }

main { max-width: 760px; margin: 0 auto; padding: 12px 12px calc(150px + env(safe-area-inset-bottom)); }
.tab { display: none; } .tab.on { display: block; }
.card { background: var(--card); border-radius: 12px; padding: 14px; margin-bottom: 12px; }
.card h3 { margin: 0 0 8px; font-size: 15px; }

nav { position: fixed; bottom: 0; left: 0; right: 0; display: flex; background: var(--card);
  border-top: 1px solid var(--line); padding-bottom: env(safe-area-inset-bottom); z-index: 6; }
nav button { flex: 1; background: transparent; border-radius: 0; padding: 12px 0; color: var(--dim); }
nav button.on { color: var(--accent); font-weight: 600; }

/* 今天 */
.status { display: flex; gap: 8px; align-items: center; margin-bottom: 4px; }
.pill { font-size: 12px; padding: 2px 8px; border-radius: 99px; background: var(--line); color: var(--dim); }
.pill.on { background: var(--ok); color: #111; }
.pill.light { background: #3a3320; color: var(--accent); }
.subj { border-left: 4px solid var(--c); }
.subj .row1 { display: flex; justify-content: space-between; align-items: baseline; }
.subj .name { font-weight: 600; }
.subj .mins { color: var(--dim); font-size: 13px; }
.bar { height: 6px; background: var(--line); border-radius: 3px; margin: 8px 0; overflow: hidden; }
.bar > i { display: block; height: 100%; background: var(--c); width: 0; transition: width .3s; }
.next { font-size: 13px; margin: 6px 0 10px; }
.next b { color: var(--fg); font-weight: 500; }
.btns { display: flex; gap: 8px; flex-wrap: wrap; }
.btns button { padding: 7px 12px; font-size: 14px; }
.btns .go { background: var(--c); color: #111; font-weight: 600; }
.quick { display: flex; gap: 8px; flex-wrap: wrap; }
.chk { display: flex; align-items: center; gap: 6px; padding: 7px 12px; border-radius: 8px; background: var(--line);
  cursor: pointer; user-select: none; font-size: 14px; }
.chk.on { background: var(--ok); color: #111; }
.log { font-size: 13px; color: var(--dim); }
.log div { display: flex; justify-content: space-between; padding: 3px 0; border-bottom: 1px dashed var(--line); }
.log div:last-child { border: 0; }
.log .x { background: transparent; padding: 0 6px; color: var(--dim); }
.grid2 { display: grid; grid-template-columns: 1fr 1fr; gap: 0 10px; }
.stars { display: flex; gap: 6px; }
.stars span { width: 34px; height: 34px; border-radius: 8px; background: var(--line); display: grid; place-items: center;
  cursor: pointer; }
.stars span.on { background: var(--accent); color: #111; }

/* 课时 */
.seg { display: flex; gap: 6px; margin-bottom: 12px; flex-wrap: wrap; }
.seg button.on { background: var(--c, var(--accent)); color: #111; font-weight: 600; }
details { background: var(--card); border-radius: 12px; margin-bottom: 8px; }
details > summary { padding: 12px 14px; cursor: pointer; list-style: none; display: flex; justify-content: space-between; }
details > summary::-webkit-details-marker { display: none; }
.chap { padding: 0 14px 8px; }
.chap h4 { margin: 10px 0 4px; font-size: 13px; color: var(--dim); font-weight: 500; }
.ls { display: flex; align-items: center; gap: 10px; padding: 6px 0; border-top: 1px solid var(--line); cursor: pointer; }
.ls .box { width: 20px; height: 20px; border-radius: 5px; border: 2px solid var(--line); flex: none; }
.ls.done .box { background: var(--c); border-color: var(--c); }
.ls.done .t { color: var(--dim); text-decoration: line-through; }
.ls.cur .t { color: var(--c); font-weight: 600; }
.ls .d { margin-left: auto; font-size: 12px; color: var(--dim); }

/* 统计 */
.heat { display: grid; grid-template-rows: repeat(7, 1fr); grid-auto-flow: column; gap: 3px; overflow-x: auto;
  padding-bottom: 4px; }
.heat i { width: 13px; height: 13px; border-radius: 3px; background: var(--line); }
.heat i.l1 { background: #3d5a45; } .heat i.l2 { background: #4f8a5f; } .heat i.l3 { background: #6cc98a; }
.heat i.today { outline: 1px solid var(--fg); }
.kpis { display: grid; grid-template-columns: repeat(3, 1fr); gap: 8px; text-align: center; }
.kpis b { display: block; font-size: 22px; color: var(--accent); }
.week { display: flex; align-items: flex-end; gap: 6px; height: 120px; }
.week .col { flex: 1; display: flex; flex-direction: column-reverse; height: 100%; }
.week .col i { display: block; }
.lb { display: flex; gap: 6px; font-size: 12px; color: var(--dim); }
.lb span { flex: 1; text-align: center; }
.prog .r { display: flex; align-items: center; gap: 10px; margin: 6px 0; font-size: 13px; }
.prog .r span:first-child { width: 90px; }
.prog .r .bar { flex: 1; margin: 0; }
.prog .r span:last-child { width: 70px; text-align: right; color: var(--dim); }

/* 计划 */
.phase { border-left: 4px solid var(--line); }
.phase.now { border-color: var(--accent); }
.phase ul { margin: 6px 0 0; padding-left: 18px; }
ol.rules { padding-left: 20px; margin: 0; } ol.rules li { margin: 4px 0; }

/* 计时条 */
.timerbar { position: fixed; left: 12px; right: 12px; bottom: calc(60px + env(safe-area-inset-bottom)); z-index: 7;
  max-width: 736px; margin: 0 auto; background: #2a2416; border: 1px solid var(--accent); border-radius: 12px;
  padding: 10px 14px; }
.timerbar b { font-size: 22px; color: var(--accent); font-variant-numeric: tabular-nums; margin-left: 8px; }
.tlesson { font-size: 13px; color: var(--dim); margin: 2px 0 8px; }
.tbtns { display: flex; gap: 8px; }

.toast { position: fixed; left: 50%; top: 70px; transform: translateX(-50%); background: var(--fg); color: #111;
  padding: 8px 16px; border-radius: 8px; opacity: 0; pointer-events: none; transition: opacity .2s; z-index: 9; }
.toast.on { opacity: 1; }

@media (min-width: 900px) {
  main { max-width: 1000px; }
  #tab-today.on { display: grid; grid-template-columns: 1fr 1fr; gap: 0 12px; align-items: start; }
  #tab-today .full { grid-column: 1 / -1; }
}

/* 第二版：课表、AI、弹窗 */
nav button { font-size: 14px; }
.row1 { display: flex; justify-content: space-between; align-items: center; gap: 8px; }
.row1 h3 { margin: 0; }
button.mini { padding: 4px 10px; font-size: 13px; }
button:disabled { opacity: .5; }
.aitext { font-size: 14px; margin-top: 8px; line-height: 1.7; }
.ttrow { display: flex; gap: 12px; padding: 8px 0; border-top: 1px solid var(--line); font-size: 14px; }
.ttrow:first-of-type { border-top: 0; }
.ttrow .tm { width: 44px; flex: none; color: var(--dim); font-size: 12px; font-variant-numeric: tabular-nums; line-height: 1.4; }
.ttrow.free b { color: var(--ok); }
.ttrow.now { background: #2a2416; margin: 0 -14px; padding: 8px 14px; }
.ttrow .dim { margin-top: 2px; }
.wkhead { display: flex; align-items: center; gap: 10px; margin-bottom: 8px; }
.wkhead button { padding: 4px 12px; }
.wk { display: grid; grid-template-columns: repeat(7, 1fr); gap: 4px; }
.wkday { background: var(--bg); border-radius: 8px; padding: 6px 4px; min-height: 120px; font-size: 11px; }
.wkday.today { outline: 1px solid var(--accent); }
.wkd { text-align: center; margin-bottom: 4px; }
.wkc { background: var(--line); border-radius: 4px; padding: 3px; margin-bottom: 3px; line-height: 1.3; word-break: break-all; }
.modal { position: fixed; inset: 0; background: rgba(0, 0, 0, .6); z-index: 20; display: flex; align-items: flex-end; justify-content: center; }
.mbox { background: var(--card); width: 100%; max-width: 640px; max-height: 88vh; display: flex; flex-direction: column;
  border-radius: 14px 14px 0 0; padding: 14px 14px calc(14px + env(safe-area-inset-bottom)); }
.mhead { display: flex; justify-content: space-between; align-items: flex-start; gap: 10px; margin-bottom: 8px; }
.mbody { overflow-y: auto; font-size: 14px; line-height: 1.75; margin-bottom: 10px; }
.ans { background: var(--bg); border-radius: 8px; margin-top: 8px; }
.ans summary { padding: 8px 10px; color: var(--accent); cursor: pointer; }
.ans > div, .ans { padding-bottom: 4px; }
.chkline { display: flex; align-items: center; gap: 8px; color: var(--fg); }
.chkline input { width: auto; }
@media (min-width: 700px) { .modal { align-items: center; } .mbox { border-radius: 14px; } .wkday { font-size: 12px; } }

/* 管家 */
.chat { display: flex; flex-direction: column; }
.chatlog { max-height: 46vh; overflow-y: auto; margin: 8px 0; display: flex; flex-direction: column; gap: 6px; }
.chatempty { line-height: 1.9; }
.msg { padding: 8px 12px; border-radius: 12px; max-width: 88%; font-size: 14px; line-height: 1.65; word-break: break-word; }
.msg.me { align-self: flex-end; background: var(--accent); color: #111; border-bottom-right-radius: 4px; }
.msg.bot { align-self: flex-start; background: var(--bg); border-bottom-left-radius: 4px; }
.toolcall { align-self: flex-start; font-size: 12px; color: var(--dim); padding: 0 4px; }
.chatform { display: flex; gap: 8px; align-items: flex-end; }
.chatform input, .chatform textarea { flex: 1; }
.chatform textarea { resize: none; min-height: 0; max-height: 140px; overflow-y: auto; line-height: 1.45; }
.row1 > span { display: flex; gap: 6px; }
@media (min-width: 900px) { .chatlog { max-height: 360px; } }

/* 更新 */
.updnew { margin-top: 8px; color: var(--accent); font-size: 14px; }
.updbanner { display: block; width: 100%; max-width: 760px; margin: 8px auto 0; background: #3a3320; color: var(--accent);
  font-size: 13px; padding: 6px 10px; }
.row1 > span button { white-space: nowrap; }
.wcard { border: 1px solid #3a3320; }
.whelp { background: transparent; margin: 8px 0 0; }
.whelp > summary { padding: 0; font-size: 12px; }
.whelp > div { padding-top: 6px; line-height: 1.8; }
.diag div { display: flex; justify-content: space-between; gap: 10px; font-size: 13px; padding: 3px 0; border-bottom: 1px dashed var(--line); }
.diag div span:last-child { text-align: right; word-break: break-all; }
.chatimg { display: block; max-width: 180px; max-height: 180px; border-radius: 8px; margin-bottom: 4px; cursor: zoom-in; }
.texph { font-family: ui-monospace, Consolas, monospace; background: #0002; border-radius: 4px; padding: 0 3px; }
.katex-display { margin: 6px 0; overflow-x: auto; overflow-y: hidden; }
.msg.streaming { white-space: normal; }
.chatlive { display: flex; flex-direction: column; gap: 6px; align-items: flex-start; min-height: 0; }
.chatlive:empty { display: none; }
.chatlive [hidden] { display: none !important; }
.msg.bot p { margin: 0 0 6px; }
.msg.bot p:last-child, .msg.bot ul:last-child, .msg.bot ol:last-child, .msg.bot pre:last-child, .msg.bot .mdtbl:last-child { margin-bottom: 0; }
.msg.bot .mdh { font-weight: 600; margin: 6px 0 4px; }
.msg.bot ul, .msg.bot ol { margin: 0 0 6px; padding-left: 20px; }
.msg.bot li { margin: 2px 0; }
.msg.bot blockquote { margin: 4px 0 6px; padding: 2px 10px; border-left: 3px solid var(--line); color: var(--dim); }
.msg.bot hr { border: 0; border-top: 1px solid var(--line); margin: 8px 0; }
.msg.bot a { color: var(--accent); word-break: break-all; }
.msg.bot i { font-style: italic; }
.mdcode { background: #0003; border-radius: 6px; padding: 8px 10px; margin: 4px 0 6px; overflow-x: auto; max-width: 100%; }
.mdcode code { font-family: ui-monospace, Consolas, monospace; font-size: 12.5px; line-height: 1.5; white-space: pre; }
.mdic { font-family: ui-monospace, Consolas, monospace; font-size: 12.5px; background: #0003; border-radius: 4px; padding: 0 4px; }
.mdtbl { overflow-x: auto; margin: 4px 0 6px; max-width: 100%; }
.mdtbl table { border-collapse: collapse; font-size: 13px; }
.mdtbl th, .mdtbl td { border: 1px solid var(--line); padding: 3px 7px; text-align: left; vertical-align: top; }
.mdtbl th { background: #0002; font-weight: 600; }
.msg.streaming .caret { display: inline-block; width: 7px; margin-left: 1px; animation: caret 1s steps(1) infinite; }
@keyframes caret { 50% { opacity: 0; } }
.thinkbtn { display: block; background: transparent; color: var(--dim); font-size: 12px; padding: 2px 6px; text-align: left; align-self: flex-start; }
.thinkbtn:hover { color: var(--fg); }
.thinkbtn span { color: var(--accent); }
.thinkbody { background: var(--bg); border-left: 3px solid var(--line); color: var(--dim); font-size: 12px; line-height: 1.65;
  padding: 6px 9px; margin: 2px 0 6px; max-height: 240px; overflow: auto; white-space: pre-wrap; border-radius: 0 8px 8px 0; }
#aud { width: 100%; margin-bottom: 6px; }
.audbtns { flex-wrap: wrap; align-items: center; gap: 6px; }
.audbtns button { min-width: 56px; }
.audbtns button.on { background: var(--accent); color: #111; }

/* ---------- AI 调用日志 ---------- */
.dbg { max-height: 72vh; overflow: auto; }
.dbgturn { border-top: 1px solid var(--line); padding: 6px 0; font-size: 13px; }
.dbgturn:first-child { border-top: 0; }
.dbgturn summary { cursor: pointer; }
.dbgturn summary b { font-weight: 600; }
.dbgr { margin: 4px 0 4px 10px; }
.dbgr summary { color: var(--dim); font-size: 12px; cursor: pointer; }
.dbg pre, .dbgtool pre { white-space: pre-wrap; word-break: break-all; font-size: 11px; line-height: 1.5; color: var(--dim); max-height: 220px; overflow: auto; background: var(--bg); border-radius: 6px; padding: 6px 8px; margin: 4px 0; }
.dbgtool { margin: 4px 0 4px 10px; }
.dbgerr { color: var(--pol); font-size: 12px; }
.chatimgs { display: flex; flex-wrap: wrap; gap: 4px; margin-bottom: 4px; }
.chatimgs .chatimg { margin-bottom: 0; max-width: 132px; max-height: 132px; }
.chatpend { display: flex; align-items: center; gap: 8px; margin-bottom: 6px; }
.chatpend img { height: 56px; border-radius: 6px; }
.chatpend .pimg { position: relative; display: inline-flex; }
.chatpend .pimg button { position: absolute; top: -7px; right: -7px; width: 20px; height: 20px; padding: 0; border-radius: 50%;
  background: var(--line); color: var(--fg); line-height: 1; font-size: 13px; }
/* 文件选择框直接铺在 ＋ 上，手机 WebView 里比 display:none + .click() 可靠 */
.chatform .attach { position: relative; flex: none; display: inline-flex; }
.chatform .attach > button { padding: 8px 12px; pointer-events: none; }
.chatform .attach > input[type=file] { position: absolute; inset: 0; width: 100%; height: 100%; opacity: 0; padding: 0; border: 0; cursor: pointer; }
.memlist .mem { display: flex; gap: 8px; align-items: flex-start; padding: 6px 0; border-top: 1px solid var(--line); font-size: 14px; }
.memlist .mem:first-child { border-top: 0; }
.memlist .mem .t { flex: 1; }
.memlist .tag { font-size: 11px; padding: 1px 6px; border-radius: 99px; background: var(--line); color: var(--dim); white-space: nowrap; }

/* 自定义日程、对话设置 */
.evtag { font-size: 11px; padding: 1px 6px; border-radius: 99px; background: #23324a; color: var(--cs); }
.wkc.ev { background: #23324a; }
.chatctl { background: var(--bg); border-radius: 10px; padding: 10px; margin-top: 8px; }
.chatctl .seg { margin-bottom: 8px; }
.chatctl textarea { font-size: 13px; }
#chatCtlBtn.on { background: var(--accent); color: #111; }
.ctxlist { max-height: 44vh; overflow-y: auto; margin-top: 6px; }
.ctxm { border-left: 3px solid var(--line); padding: 4px 8px; margin: 4px 0; cursor: pointer; border-radius: 0 6px 6px 0; }
.ctxm:hover { background: var(--card); }
.ctxm.r-user { border-color: var(--accent); }
.ctxm.r-assistant { border-color: var(--ok); }
.ctxm.r-tool { border-color: var(--cs); }
.ctxm.out { opacity: .4; }
.ctxh { display: flex; justify-content: space-between; font-size: 12px; }
.ctxt { font-size: 12px; white-space: pre-wrap; word-break: break-all; color: var(--dim); }
.syspre { white-space: pre-wrap; font-size: 11px; color: var(--dim); max-height: 40vh; overflow: auto; }

/* 目标 */
.goal { border-left: 4px solid var(--accent); }
.goal.warn { border-color: #e0a84f; } .goal.bad { border-color: var(--pol); } .goal.good { border-color: var(--ok); opacity: .75; }
.gst { font-size: 11px; padding: 1px 7px; border-radius: 99px; background: var(--line); color: var(--dim); }
.gst.warn { background: #3a3320; color: var(--accent); } .gst.bad { background: #3a2020; color: var(--pol); } .gst.good { background: #1f3a28; color: var(--ok); }
.gk { display: flex; align-items: center; gap: 8px; padding: 6px 0; border-top: 1px solid var(--line); font-size: 14px; }
.gk .t { flex: 1; }
.gk .box { width: 20px; height: 20px; border-radius: 5px; border: 2px solid var(--line); flex: none; cursor: pointer; }
.gk.done .box { background: var(--ok); border-color: var(--ok); }
.gk.done .t { color: var(--dim); text-decoration: line-through; }
.gk .dim { font-size: 12px; white-space: nowrap; }
.gtoday { font-size: 14px; padding: 5px 0; border-top: 1px dashed var(--line); }
.gtoday:first-of-type { border-top: 0; }

/* 知识库 */
nav button { font-size: 13px; padding: 12px 0; }
.kbhit { cursor: pointer; padding: 10px 14px; }
.kbsnip { font-size: 13px; line-height: 1.7; margin-top: 4px; }
mark { background: #5a4a1a; color: var(--fg); border-radius: 2px; padding: 0 1px; }
.lv { font-size: 11px; padding: 1px 7px; border-radius: 99px; white-space: nowrap; background: var(--line); color: var(--dim); }
.lv0 { background: #3a2020; color: #e88; } .lv1 { background: #3a2a20; color: #e9a36a; } .lv2 { background: #3a3320; color: var(--accent); }
.lv3 { background: #2c3a20; color: #b9d36a; } .lv4 { background: #1f3a28; color: var(--ok); } .lv5 { background: #1f2f3a; color: var(--cs); }
.lvbtns { display: grid; grid-template-columns: repeat(3, 1fr); gap: 6px; margin-top: 6px; }
.lvb { display: flex; flex-direction: column; align-items: center; padding: 8px 4px; font-size: 14px; }
.lvb span { font-size: 10px; opacity: .7; }
.lvb.on { outline: 2px solid var(--fg); }
.lvdist { display: flex; gap: 2px; }
.lvdist .lv { border-radius: 4px; text-align: center; padding: 4px 2px; overflow: hidden; }
.rv .rvq { font-size: 16px; line-height: 1.7; margin: 10px 0; }
.rv .rvb { font-size: 14px; color: var(--dim); }
.kbcard, .kbdoc { padding: 10px 14px; }
.kbcard { cursor: pointer; }
.docch { padding: 8px 0; border-bottom: 1px dashed var(--line); font-size: 14px; line-height: 1.7; }
.docch.focus { background: #2a2416; margin: 0 -14px; padding: 8px 14px; }

/* 星级 */
.ls .stars { margin-left: 6px; white-space: nowrap; flex: none; }
.ls .stars i { font-style: normal; color: var(--line); font-size: 17px; padding: 0 1px; cursor: pointer; }
.ls .stars i.on { color: var(--accent); }
.ls.done .t { text-decoration: none; color: var(--fg); }
.ls.s5 .t { color: var(--dim); }
.ls .box { display: none; }
.revtag { font-size: 11px; padding: 0 6px; border-radius: 99px; background: #23324a; color: var(--cs); }
.revrow { display: flex; justify-content: space-between; align-items: center; gap: 8px; padding: 6px 0; border-top: 1px dashed var(--line); font-size: 14px; }
.revrow > span:last-child { display: flex; gap: 4px; flex: none; }
.starpick { display: inline-flex; gap: 4px; flex-wrap: wrap; }
.kbup { display: flex; gap: 8px; margin-bottom: 10px; }
/* 多对话 */
.thhead { margin: 0; }
.thhead button { font-weight: 600; font-size: 14px; max-width: 46vw; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
.threads { background: var(--bg); border-radius: 10px; padding: 6px 10px; margin-top: 8px; }
