  // 只给今天的块塞目标（课表页的"今天"区块用的就是今天）
  const base = _suggestForSlot(slot, idx);
  return gs.length ? gs.map(goalLine).join('<br>') + (gs.reduce((a, x) => a + (x.goal.min || 40), 0) + 40 <= slot.len ? '<br>' + base : '') : base;
};
