    runAI(b, async () => { await AI.fetchKey(); renderSet(); toast(AI.key() ? '已从电脑获取 Key' : '电脑上没配置 Key'); });
  } else if (id === 'expJson') {
    download(`北伐打卡-${today()}.json`, JSON.stringify({ app: 'beifa', v: 1, exported: Date.now(), ...S }), 'application/json');
