  }
  else if (id === 'sDocSync') {
    saveSyncFields();
    if (!window.DocSync) { toast('页面还没加载完，稍后再试'); return; }
    const old = b.textContent; b.disabled = true; b.textContent = '同步中…';
    try { await window.DocSync.run(true); } finally { b.disabled = false; b.textContent = old; }
