    <div class="btns">${[1, 2, 3, 4, 5].map(i => `<button class="${i === 3 ? 'primary' : ''}" data-gstar="${t.lesson}" data-n="${i}">${i}★ ${STAR_TEXT[i]}</button>`).join('')}
    <button class="ghost" data-close>还没学完</button></div></div>`;
