function weekMinutes() {
  const d0 = today(), mon = addDays(d0, -((parse(d0).getDay() + 6) % 7));
  let t = 0;
  for (let d = mon; d <= d0; d = addDays(d, 1)) t += Object.values(minutes(d)).reduce((a, b) => a + b, 0);
  return t;
}

